import { closeSync, existsSync, openSync, readdirSync, readFileSync, readSync } from "node:fs";
import { join, posix } from "node:path";

import { type ESTree, parseSync } from "vite-plus";

import type { ContributionFiles } from "./extensions.ts";
import type { Manifest } from "./manifest.ts";

/** Starts the first line of every generated file (after `// ` or `<!-- `). */
export const GENERATED = "Generated by scripts/modules.ts";

/** Whether the generator wrote `file`: its first line says so. */
export function isGenerated(file: string) {
	const buffer = Buffer.alloc(64);
	const fd = openSync(file, "r");
	try {
		const text = buffer.toString("utf8", 0, readSync(fd, buffer));
		return text.startsWith(`// ${GENERATED}`) || text.startsWith(`<!-- ${GENERATED}`);
	} finally {
		closeSync(fd);
	}
}

/**
 * Whether `dir` is a stub folder of the generator's earlier versions, which wrote a module's route
 * folder beside the core's (`src/routes/(app)/contracts`) with a `.gitignore` that ignored it.
 */
export function isLegacyStubFolder(dir: string) {
	const file = join(dir, ".gitignore");
	return existsSync(file) && readFileSync(file, "utf8").startsWith(`# ${GENERATED}`);
}

/**
 * What a module's folder contains that the generator needs to know about: what its `module.ts`
 * says (`readManifest()`) and its contribution files (`contributionKinds`).
 */
export interface ModuleFolder extends Omit<Manifest, "problems">, ContributionFiles {
	/** The folder's name. */
	id: string;
	/** Its `+` route files, relative to `routes/`, with `/`, sorted. */
	routeFiles: string[];
	/**
	 * What its pages show while they load, one per page, mirroring `routes/`:
	 * `skeletons/(app)/page.svelte` for `routes/(app)/+page.svelte`.
	 */
	skeletonFiles: string[];
	/** Which of the server files it has. */
	server: { index: boolean; schema: boolean; seed: boolean };
	/** Its message sections (`messages/<locale>/<section>.json`) per language, sorted. */
	messages: Record<string, string[]>;
}

export const byName = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

/** The program of `source`, a TypeScript file, as oxc parses it; throws on a syntax error. */
export function parseProgram(file: string, source: string) {
	const { program, errors } = parseSync(file, source, { sourceType: "module" });
	if (errors.length) throw new Error(`${file}: ${errors[0].message}`);
	return program;
}

/** The text of a string literal (`"a"`, `'a'`, or a template without `${}`), if `node` is one. */
export function stringOf(node: ESTree.Node | null | undefined) {
	if (node?.type === "Literal" && typeof node.value === "string") return node.value;
	if (node?.type === "TemplateLiteral" && !node.expressions.length) {
		return node.quasis[0].value.cooked ?? undefined;
	}
}

/** The properties of an object literal by key (a name or a string), if `node` is one. */
export function propertiesOf(node: ESTree.Node | null | undefined) {
	if (node?.type !== "ObjectExpression") return undefined;
	const properties = new Map<string, ESTree.Expression>();
	for (const property of node.properties) {
		if (property.type !== "Property" || property.computed) continue;
		const key = property.key.type === "Identifier" ? property.key.name : stringOf(property.key);
		if (key !== undefined) properties.set(key, property.value);
	}
	return properties;
}

/** The files under `dir`, relative to it, with `/`, sorted. */
export function walk(dir: string): string[] {
	if (!existsSync(dir)) return [];
	return readdirSync(dir, { recursive: true, withFileTypes: true })
		.filter((entry) => !entry.isDirectory())
		.map((entry) => posix.relative(dir.replaceAll("\\", "/"), join(entry.parentPath, entry.name)))
		.toSorted(byName);
}
